MINCO = "https://www.orientdisplay.com/wp-content/uploads/2022/10/Heater5.pdf"
for id, dims, resistance in (("25x25", (25, 25, 0.3), 25), ("25x50", (50, 25, 0.3), 50), ("50x50", (50, 50, 0.3), 100), ("25x100", (100, 25, 0.3), 100), ("12x50", (50, 12, 0.3), 30)):
    PARTS.append(part("polyimide_heater_" + id, "Polyimide foil heater " + id.replace("x", " x ") + " mm (Minco Thermofoil class)", "thermal", "heater", "Minco (class; sizes are custom per order)", "Polyimide Thermofoil HK-type, " + id, dims, round(dims[0] * dims[1] * 0.3 * 1.4 / 1000, 2), {"kind": "box", "x": dims[0], "y": dims[1], "z": dims[2]},
        source("derived", MINCO, "Minco Polyimide Thermofoil heater specification HTK05", ["thermal", "material"], notes="The Minco spec gives the construction (polyimide/FEP 0.05/0.03 mm, up to 0.3 mm thick over the element, max 200 C, up to 70 ohm/cm2) and custom sizes up to 250 x 560 mm; this size and resistance are a representative order, not a catalogue item. Mass DERIVED (0.3 mm x 1.4 g/cm3)."),
        vendor_country="USA", distributors=["direct", "Digi-Key (stock sizes)"], status="in_production", material="polyimide/FEP with etched foil element", mass_note="derived", thermal={"max_temperature_C": 200, "watt_density_W_cm2": 2.8}, electrical={"resistance_ohm": resistance, "voltage_V": {"nominal": 12}, "power_W": {"nominal": round(12 ** 2 / resistance, 2)}}, connectors=["AWG 26-30 lead wires (over-lead thickness 1.3-2.2 mm)"], cost=cost(basis="quote")))
TAI = "https://wiki.nikhef.nl/vuv/images/1/14/2022_CuTS%C2%AE_Catalog_-_TAI%281139%29.pdf"
for id, model, mass, conductance, rope, count in (("ufi_26x1", "UltraFlex I 26x1 (0.10 in rope)", 318, 0.31, 2.54, 26), ("ufii_9x1", "UltraFlex II 9x1 (0.20 in rope)", 352, 0.40, 5.08, 9), ("ufii_4x1", "UltraFlex II 4x1 (0.20 in rope)", 172, 0.18, 5.08, 4)):
    width = count * rope * 1.05 + 6
    PARTS.append(part("tai_cuts_" + id, "Technology Applications Inc CuTS copper thermal strap, " + model + ", 100 mm", "thermal", "thermal_strap", "Technology Applications, Inc. (TAI)", "CuTS " + model, (100 + 2 * 19, width, 6.4), mass, {"kind": "box", "x": 100 + 2 * 19, "y": width, "z": 6.4},
        source("datasheet", TAI, "TAI CuTS Catalog 2022 Edition", ["mass_g", "thermal"], notes="Mass and conductance (300 K, 100 mm rope length) from the catalog. Overall envelope DERIVED: rope length 100 mm plus two 0.75 in compact end fittings, 0.25 in thick; width from rope count x rope diameter.", date="2022"),
        vendor_country="USA", distributors=["direct"], status="in_production", material="OFHC copper rope with copper end fittings", fidelity="envelope", thermal={"conductance_W_per_K": conductance, "min_bend_radius_mm": 12.5}, dimensions_note="derived envelope", mounting={"pattern": "end fittings with bolt holes (sizes per order)"}, cost=cost(basis="quote")))
# Generic radiator plates, MLI and heat pipe sizes (derived; typical CubeSat practice, no vendor datasheet)
